      </div>
    </div>
    <div class="legend-item">
      <div class="legend-line" style="background:var(--wage);height:3px;"></div>
      <div class="legend-label">
        <strong>Nominal Wage Growth</strong>
        Year-over-year (%)
      </div>
    </div>
    <div class="legend-item">
      <div class="legend-line" style="background:var(--ffr);height:4px;border-radius:0;"></div>
      <div class="legend-label">
        <strong>Federal Funds Rate</strong>
        Effective rate (%)
      </div>
    </div>
    <div class="legend-item">
      <div class="legend-line" style="background:var(--real);height:2px;border-top:2px dashed var(--real);background:none;width:28px;border-bottom:none;border-left:none;border-right:none;height:0;"></div>
      <div class="legend-label">
        <strong>Real Wage Growth</strong>
        Nominal wages − CPI (%)
      </div>
    </div>
  </div>

  <div class="chart-shell">
    <div class="chart-wrap">
      <canvas id="inflationChart"></canvas>
    </div>
  </div>

  <div class="annotations">
    <div class="annotation-card" style="--accent-color: var(--cpi);">
      <div class="label">Peak Inflation</div>
      <div class="value">9.1%</div>
      <div class="desc">CPI peak in June 2022 — the highest since 1981. Fed rate hikes began 4 months earlier in March 2022.</div>
    </div>
    <div class="annotation-card" style="--accent-color: var(--ffr);">
      <div class="label">Rate Hike Campaign</div>
      <div class="value">+5.25 pp</div>
      <div class="desc">The Fed raised rates from near-zero (0.08%) to 5.33% between March 2022 and July 2023 — the steepest tightening cycle in decades.</div>
    </div>
    <div class="annotation-card" style="--accent-color: var(--real);">
      <div class="label">Real Wage Recovery</div>
      <div class="value">May 2023</div>
      <div class="desc">Real wages turned positive after 25 consecutive months of negative territory (Apr 2021 – Apr 2023), as CPI fell below nominal wage growth.</div>
    </div>
  </div>

  <p class="source-note">
    Sources: Bureau of Labor Statistics (CPI-U All Items, Average Hourly Earnings); Federal Reserve Board H.15.
    Real wage growth = nominal wage growth − CPI inflation (arithmetic approximation). Monthly data, Jan 2021–Dec 2024.
  </p>

</div>

<script>
// ── Data ──────────────────────────────────────────────────────────────────────
const labels = [
  "Jan'21","Feb'21","Mar'21","Apr'21","May'21","Jun'21","Jul'21","Aug'21","Sep'21","Oct'21","Nov'21","Dec'21",
  "Jan'22","Feb'22","Mar'22","Apr'22","May'22","Jun'22","Jul'22","Aug'22","Sep'22","Oct'22","Nov'22","Dec'22",
  "Jan'23","Feb'23","Mar'23","Apr'23","May'23","Jun'23","Jul'23","Aug'23","Sep'23","Oct'23","Nov'23","Dec'23",
  "Jan'24","Feb'24","Mar'24","Apr'24","May'24","Jun'24","Jul'24","Aug'24","Sep'24","Oct'24","Nov'24","Dec'24"
];

const cpi = [1.4,1.7,2.6,4.2,5.0,5.4,5.4,5.3,5.4,6.2,6.8,7.0,7.5,7.9,8.5,8.3,8.6,9.1,8.5,8.3,8.2,7.7,7.1,6.5,6.4,6.0,5.0,4.9,4.0,3.0,3.2,3.7,3.7,3.2,3.1,3.4,3.1,3.2,3.5,3.4,3.3,3.0,2.9,2.5,2.4,2.6,2.7,2.9];
const wage = [5.4,5.2,4.2,0.7,1.9,3.7,4.1,4.3,4.6,5.0,5.1,5.0,5.5,5.2,5.6,5.5,5.3,5.2,5.2,5.2,5.0,4.8,4.8,4.6,4.4,4.6,4.3,4.4,4.4,4.4,4.4,4.3,4.3,4.2,4.3,4.3,4.4,4.3,4.1,3.9,4.1,3.9,3.6,3.8,4.0,4.0,4.0,3.9];
const ffr  = [0.09,0.08,0.07,0.07,0.06,0.08,0.10,0.09,0.08,0.08,0.08,0.08,0.08,0.08,0.33,0.33,0.83,1.58,2.33,2.33,3.08,3.08,3.83,4.33,4.33,4.58,4.83,4.83,5.08,5.08,5.33,5.33,5.33,5.33,5.33,5.33,5.33,5.33,5.33,5.33,5.33,5.33,5.33,5.33,4.83,4.83,4.58,4.33];
const real = [4.0,3.5,1.6,-3.5,-3.1,-1.7,-1.3,-1.0,-0.8,-1.2,-1.7,-2.0,-2.0,-2.7,-2.9,-2.8,-3.3,-3.9,-3.3,-3.1,-3.2,-2.9,-2.3,-1.9,-2.0,-1.4,-0.7,-0.5,0.4,1.4,1.2,0.6,0.6,1.0,1.2,0.9,1.3,1.1,0.6,0.5,0.8,0.9,0.7,1.3,1.6,1.4,1.3,1.0];

// ── Build above/below-zero fill data ─────────────────────────────────────────
// For real wage: fill negative region in terracotta, positive in emerald
const realAbove = real.map(v => v >= 0 ? v : NaN);
const realBelow = real.map(v => v <  0 ? v : NaN);

// ── Chart.js config ───────────────────────────────────────────────────────────
const ctx = document.getElementById('inflationChart').getContext('2d');

// Create gradient fills
function makeGradient(ctx, color, yTop, yBottom) {
  const grad = ctx.createLinearGradient(0, yTop, 0, yBottom);
  grad.addColorStop(0, color);
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  return grad;
}

// Annotation plugin (inline — no external plugin needed)
// We draw phase boxes & annotations manually in afterDraw

const peakZonePlugin = {
  id: 'phaseAnnotations',
  afterDraw(chart) {
    const { ctx, scales, chartArea } = chart;
    const xScale = scales.x;
    const yScale = scales.y;

    ctx.save();

    // Peak inflation zone: Mar 2022 (index 14) → Sep 2022 (index 20)
    const x0peak = xScale.getPixelForValue(14);
    const x1peak = xScale.getPixelForValue(20);
    ctx.fillStyle = 'rgba(194,65,12,0.06)';
    ctx.fillRect(x0peak, chartArea.top, x1peak - x0peak, chartArea.bottom - chartArea.top);

    // Rate hike start marker: Mar 2022 (index 14)
    const xHike = xScale.getPixelForValue(14);
    ctx.setLineDash([5, 4]);
    ctx.strokeStyle = 'rgba(30,58,95,0.35)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(xHike, chartArea.top + 2);
    ctx.lineTo(xHike, chartArea.bottom);
    ctx.stroke();
    ctx.setLineDash([]);

    // Annotation: "Fed hikes begin" label
    ctx.fillStyle = 'rgba(30,58,95,0.75)';
    ctx.font = "500 10px 'IBM Plex Mono', monospace";
    ctx.textAlign = 'left';
    ctx.fillText('Fed hikes begin', xHike + 5, chartArea.top + 16);
    ctx.fillText('Mar 2022', xHike + 5, chartArea.top + 29);

    // Peak annotation: Jun 2022 (index 17) — 9.1%
    const xPeak = xScale.getPixelForValue(17);
    const yPeak = yScale.getPixelForValue(9.1);
    ctx.fillStyle = '#c2410c';
    ctx.font = "600 11px 'IBM Plex Mono', monospace";
    ctx.textAlign = 'center';
    ctx.fillText('9.1% peak', xPeak, yPeak - 10);

    // Real wage recovery: May 2023 (index 28)
    const xRecov = xScale.getPixelForValue(28);
    ctx.setLineDash([4, 3]);
    ctx.strokeStyle = 'rgba(5,150,105,0.5)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(xRecov, chartArea.top + 2);
    ctx.lineTo(xRecov, chartArea.bottom);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.fillStyle = 'rgba(5,150,105,0.8)';
    ctx.font = "500 10px 'IBM Plex Mono', monospace";
    ctx.textAlign = 'left';
    ctx.fillText('Real wages', xRecov + 5, chartArea.bottom - 36);
    ctx.fillText('turn positive', xRecov + 5, chartArea.bottom - 23);
    ctx.fillText('May 2023', xRecov + 5, chartArea.bottom - 10);

    // Zero reference line label
    const yZero = yScale.getPixelForValue(0);
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.font = "400 9.5px 'IBM Plex Mono', monospace";
    ctx.textAlign = 'right';
    ctx.fillText('0%', chartArea.left - 4, yZero + 3.5);

    // Lag bracket between rate hike (Mar 2022, idx=14) and CPI peak (Jun 2022, idx=17)
    const xLagA = xScale.getPixelForValue(14);
    const xLagB = xScale.getPixelForValue(17);
    const yBracket = chartArea.top + 50;
    ctx.strokeStyle = 'rgba(30,58,95,0.45)';
    ctx.lineWidth = 1.3;
    ctx.setLineDash([]);
    // bracket
    ctx.beginPath();
    ctx.moveTo(xLagA, yBracket + 5);
    ctx.lineTo(xLagA, yBracket);
    ctx.lineTo(xLagB, yBracket);
    ctx.lineTo(xLagB, yBracket + 5);
    ctx.stroke();
    // arrow heads
    ctx.fillStyle = 'rgba(30,58,95,0.45)';
    [xLagA, xLagB].forEach((x, i) => {
      ctx.beginPath();
      ctx.moveTo(x, yBracket + 5);
      ctx.lineTo(x - 4, yBracket);
      ctx.lineTo(x + 4, yBracket);
      ctx.closePath();
      ctx.fill();
    });
    ctx.font = "400 9.5px 'IBM Plex Mono', monospace";
    ctx.fillStyle = 'rgba(30,58,95,0.65)';
    ctx.textAlign = 'center';
    ctx.fillText('~3 mo lag', (xLagA + xLagB) / 2, yBracket - 4);

    ctx.restore();
  }
};

const chart = new Chart(ctx, {
  type: 'line',
  plugins: [peakZonePlugin],
  data: {
    labels,
    datasets: [
      // Federal Funds Rate — thick navy step-like line
      {
        label: 'Federal Funds Rate',
        data: ffr,
        borderColor: '#1e3a5f',
        borderWidth: 3.5,
        pointRadius: 0,
        pointHoverRadius: 5,
        tension: 0.05,
        stepped: false,
        fill: false,
        order: 4,
        yAxisID: 'y',
        z: 4
      },
      // CPI Inflation — bold terracotta
      {
        label: 'CPI Inflation',
        data: cpi,
        borderColor: '#c2410c',
        borderWidth: 2.5,
        pointRadius: 0,
        pointHoverRadius: 5,
        tension: 0.3,
        fill: false,
        order: 3,
        yAxisID: 'y',
        z: 3
      },
      // Nominal Wage Growth — steel blue
      {
        label: 'Nominal Wage Growth',
        data: wage,
        borderColor: '#0369a1',
        borderWidth: 2.2,
        pointRadius: 0,
        pointHoverRadius: 5,
        tension: 0.3,
        fill: false,
        order: 2,
        yAxisID: 'y',
        z: 2
      },
      // Real Wage Growth (positive) — emerald dashed
      {
        label: 'Real Wage Growth (positive)',
        data: realAbove,
        borderColor: '#059669',
        borderWidth: 2,
        borderDash: [5, 4],
        pointRadius: 0,
        pointHoverRadius: 4,
        tension: 0.3,
        fill: {
          target: { value: 0 },
          above: 'rgba(5,150,105,0.08)',
          below: 'transparent'
        },
        order: 1,
        yAxisID: 'y',
        z: 1
      },
      // Real Wage Growth (negative) — same line continued, negative zone fill
      {
        label: 'Real Wage Growth (negative)',
        data: realBelow,
        borderColor: '#059669',
        borderWidth: 2,
        borderDash: [5, 4],
        pointRadius: 0,
        pointHoverRadius: 4,
        tension: 0.3,
        fill: {
          target: { value: 0 },
          above: 'transparent',
          below: 'rgba(194,65,12,0.10)'
        },
        order: 0,
        yAxisID: 'y',
        z: 0
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    interaction: {
      mode: 'index',
      intersect: false
    },
    plugins: {
      legend: { display: false },
      tooltip: {
        backgroundColor: 'rgba(26,21,16,0.92)',
        titleFont: { family: "'IBM Plex Mono', monospace", size: 11, weight: '500' },
        bodyFont:  { family: "'IBM Plex Sans', system-ui, sans-serif", size: 12.5 },
        titleColor: '#f0e8df',
        bodyColor: '#ccc0b4',
        padding: 12,
        borderColor: 'rgba(255,255,255,0.10)',
        borderWidth: 1,
        callbacks: {
          title(items) { return items[0].label; },
          label(item) {
            const labels = [
              'Fed Funds Rate',
              'CPI Inflation',
              'Wage Growth (Nominal)',
              'Real Wage Growth',
              null
            ];
            const name = labels[item.datasetIndex];
            if (!name || item.parsed.y === null || isNaN(item.parsed.y)) return null;
            return `  ${name}: ${item.parsed.y.toFixed(2)}%`;
          }
        }
      }
    },
    scales: {
      x: {
        grid: {
          color: 'rgba(0,0,0,0.04)',
          drawTicks: false
        },
        border: { color: 'rgba(0,0,0,0.12)' },
        ticks: {
          font: { family: "'IBM Plex Mono', monospace", size: 9.5 },
          color: '#9b8878',
          maxRotation: 0,
          autoSkip: true,
          maxTicksLimit: 16,
          callback(val, idx) {
            // Only show Jan of each year + Jun 2022 peak area
            const l = labels[idx];
            if (l.startsWith("Jan")) return l.replace("Jan'", "'");
            if (l === "Jun'22") return "Jun'22";
            if (l === "Jun'23") return "Jun'23";
            return null;
          }
        }
      },
      y: {
        min: -5,
        max: 10.5,
        grid: {
          color(ctx) {
            if (ctx.tick.value === 0) return 'rgba(0,0,0,0.25)';
            return 'rgba(0,0,0,0.05)';
          },
          lineWidth(ctx) {
